{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - sum(seg['minimum'] for seg in segments)
    indices = sorted(range(n), key=lambda i: segments[i]['importance'], reverse=True)
    for i in indices:
        max_add = min(remaining, segments[i]['capacity'] - allocations[i])
        if max_add > 0:
            allocations[i] += max_add
            remaining -= max_add
        if remaining == 0:
            break
    total = sum(allocations)
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {'allocations': allocations, 'by_name': by_name, 'total': total}
